#!/usr/bin/env python3
# Bio 101 - Quiz 3 grader
# Reads quiz3_responses.csv (columns: student,q1,q2,q3 - each out of 10, 30 total)
# and prints one line per student: name, total, letter grade.
# Letter grade on the total out of 30: A >= 27, B >= 24, C >= 21, D >= 18, else F

import csv

CSV_PATH = "quiz3_responses.csv"

def letter(total):
    if total >= 27:
        return "A"
    elif total >= 24:
        return "B"
    elif total >= 21:
        return "C"
    elif total >= 18:
        return "D"
    else:
        return "F"

def main():
    with open(CSV_PATH, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            name = row["student"]
            total = int(row["q1"]) + int(row["q2"]) + int(row["q3"])
            print(f"{name} {total} {letter(total)}")

if __name__ == "__main__":
    main()
EOF")
